"""Builds src/data/vestibu-inhalte.vi.json (Vietnamese content) from vi_greetings.txt and the tables below.
Run after re-importing the German Excel: python scripts/build-vi.py"""
import json
from pathlib import Path
root = Path(__file__).resolve().parent.parent
de = json.loads((root/'src/data/vestibu-inhalte.json').read_text(encoding='utf8'))
greet = (root/'scripts/vi_greetings.txt').read_text(encoding='utf8').strip().split('\n')
